# ============================================================ S25
add_divider("Session 25 · Lecture hour 4 (of 15)","ORDER BY · DISTINCT · Set Operations",
    "A merit list isn't useful unless it's SORTED, and a mailing list isn't useful if every name appears five times. SQL fixes both — one keyword each.",
    "OPENING HOOK [~5 min]. Agenda: ORDER BY (sorting) → DISTINCT (de-duplication) → UNION/INTERSECT/EXCEPT (combining result sets). Pin the schema.")

concept_understand("S25 · Concept 1 · [THEORY] [SNIPPET]","Ordering the Display (ORDER BY)",
    "ORDER BY sorts the result rows. ASC (ascending) is the default; DESC is descending. Multiple sort keys break ties left to right. In MySQL, LIMIT n returns just the first n rows (useful for top-N).",
    ["SELECT name, marks FROM Enrollment ORDER BY marks DESC; — highest first.",
     "Multi-key: ORDER BY marks DESC, name ASC — ties broken by name.",
     "MySQL LIMIT 3 after ORDER BY gives the top 3 (merit list top rows).",
     "Rows have NO reliable order without ORDER BY — never assume one."],
    None,"No ORDER BY = no promised order. Want a merit list? You must sort it.",
    "~8 min. Merit list = ORDER BY marks DESC, name ASC. Top 3 = ...ORDER BY marks DESC LIMIT 3.")
add_table_slide("S25 · Concept 1 · examples","ORDER BY — goal → clause → what you get",
    ["Goal","Clause (MySQL)","Result"],
    [["merit list, best first","ORDER BY marks DESC","88, 76, 55, 40…"],
     ["alphabetical roll","ORDER BY name ASC","Anjali, Bishal, Gita…"],
     ["ties broken by name","ORDER BY marks DESC, name ASC","same marks → A before B"],
     ["top 3 scorers","ORDER BY marks DESC LIMIT 3","the three highest rows"],
     ["cheapest 5 products","ORDER BY price ASC LIMIT 5","5 lowest prices"],
     ["newest first","ORDER BY created_at DESC","latest transactions on top"]],
    per_page=6,widths=[2.2,2.8,2.0],fs=10.5,
    note="ASC is the default; add DESC for descending. LIMIT (MySQL) after ORDER BY is the standard 'top-N' idiom. Without ORDER BY, row order is not guaranteed.")
concept_apply("S25 · Concept 1 · [THEORY]","Ordering the Display (ORDER BY)",
    "A college merit list is ORDER BY marks DESC, name ASC; Daraz 'sort by price: low to high' is ORDER BY price ASC; 'top sellers' is ORDER BY units_sold DESC LIMIT 10. Any 'sorted by…' control in an app is an ORDER BY.",
    "\"Rows come back sorted by default.\" They do NOT — without ORDER BY the DBMS may return rows in any order (and it can change between runs). If order matters, you must state it explicitly.",
    "ORDER BY sorts result rows by one or more keys; ASC (default) is ascending, DESC descending, and multiple keys break ties left to right. In MySQL, LIMIT n returns the first n rows for top-N queries. Without ORDER BY, row order is undefined and must never be assumed.",
    "ORDER BY · ASC/DESC · multi-key sort · LIMIT (MySQL) · order not guaranteed")

concept_understand("S25 · Concept 2 · [THEORY] [SNIPPET]","Duplicate Tuples (DISTINCT / ALL)",
    "SELECT keeps duplicate rows by default (ALL). DISTINCT removes duplicate rows from the result, so each distinct combination of the selected columns appears once.",
    ["SELECT DISTINCT program FROM Student; — one row per program.",
     "SELECT program FROM Student; — repeats a program once per student.",
     "DISTINCT applies to the WHOLE selected row, not one column.",
     "ALL is the (rarely written) default that keeps duplicates."],
    None,"DISTINCT = 'one of each, please' — collapse repeats to a single row.",
    "~7 min. List distinct districts from a Nagarik App users table; distinct programs from Student.")
add_table_slide("S25 · Concept 2 · examples","DISTINCT vs ALL — same query, different result",
    ["Query","Returns","Rows (seed data)"],
    [["SELECT program FROM Student","every student's program (repeats)","BIM, BIM, BCA, BIM, BCA"],
     ["SELECT DISTINCT program FROM Student","each program once","BIM, BCA"],
     ["SELECT dept FROM Instructor","dept per instructor","IT, IT, MGT, ECO"],
     ["SELECT DISTINCT dept FROM Instructor","each dept once","IT, MGT, ECO"],
     ["SELECT DISTINCT program, semester FROM Student","distinct COMBINATIONS","(BIM,4),(BCA,4),(BIM,6),(BCA,2)"],
     ["distinct districts (Nagarik App)","SELECT DISTINCT district FROM users","one row per district"]],
    per_page=6,widths=[3.0,2.2,1.8],fs=10.5,
    note="DISTINCT de-duplicates the ENTIRE selected row. Selecting two columns with DISTINCT keeps each distinct pair — not each column de-duplicated separately.")
concept_apply("S25 · Concept 2 · [THEORY]","Duplicate Tuples (DISTINCT / ALL)",
    "A 'choose your district' dropdown is SELECT DISTINCT district FROM users — you want each district once, not repeated per user. A tag cloud, a filter list, a 'departments we hire in' list — all are DISTINCT queries over a column with many repeats.",
    "\"DISTINCT de-duplicates just the first column.\" No — DISTINCT considers the WHOLE selected row. SELECT DISTINCT program, semester returns each distinct (program, semester) PAIR, so a program can still appear several times with different semesters.",
    "By default SELECT returns all rows including duplicates (ALL). DISTINCT removes duplicate rows so each distinct combination of the selected columns appears once. It applies to the entire selected row, not a single column — SELECT DISTINCT a, b de-duplicates the (a,b) pairs.",
    "DISTINCT · ALL (default) · de-duplication · whole-row · distinct combinations")

concept_understand("S25 · Concept 3 · [THEORY] [SNIPPET]","Set Operations: UNION / INTERSECT / EXCEPT",
    "Set operations combine two result sets that are UNION-COMPATIBLE (same number of columns, compatible types). UNION = rows in either; INTERSECT = rows in both; EXCEPT = rows in the first but not the second.",
    ["UNION stacks two results and removes duplicates; UNION ALL keeps them.",
     "INTERSECT keeps rows appearing in both queries; EXCEPT subtracts the second from the first.",
     "Both queries must return the same columns in the same order (union-compatible).",
     "MySQL note: UNION is native; older MySQL lacks INTERSECT/EXCEPT (emulate with IN / NOT IN or joins) — MariaDB 10.3+ and MySQL 8.0.31+ support them."],
    "s25_setops.png","Venn: UNION = both circles, INTERSECT = overlap, EXCEPT = left minus overlap.",
    "~10 min. DBMS students INTERSECT Economics students; eSewa users EXCEPT Khalti users. Flag the MySQL support caveat.")
add_table_slide("S25 · Concept 3 · comparison","The three set operations — what each keeps",
    ["Operation","Keeps rows that are…","Duplicates?","College / Nepal example"],
    [["UNION","in query A OR query B","removed","students in IT220 OR MGT201"],
     ["UNION ALL","in A or B","KEPT","combine two logs, keep every entry"],
     ["INTERSECT","in BOTH A and B","removed","students in DBMS AND Economics"],
     ["EXCEPT","in A but NOT in B","removed","eSewa users EXCEPT Khalti users"],
     ["(union-compatible)","same #cols + compatible types","-","required for all three"]],
    per_page=5,widths=[1.6,2.4,1.1,2.6],fs=10.5,
    note="Union-compatibility (same columns, same order, compatible types) is mandatory. UNION removes duplicates; UNION ALL keeps them — and UNION ALL is faster when you know there are none.")
concept_apply("S25 · Concept 3 · [THEORY]","Set Operations",
    "Marketing segments are set operations: 'users in A but not B' (EXCEPT) targets 'registered but never paid'; 'in both A and B' (INTERSECT) finds cross-app users; 'in either' (UNION) merges two campaign lists into one de-duplicated mailing list.",
    "\"UNION keeps duplicates.\" No — UNION removes duplicates; UNION ALL keeps them. Also, the two queries must be union-compatible: same number of columns, in the same order, with compatible types — otherwise it errors.",
    "Set operations combine two union-compatible result sets: UNION (rows in either, duplicates removed), UNION ALL (rows in either, duplicates kept), INTERSECT (rows in both), and EXCEPT/MINUS (rows in the first but not the second). Both queries must return the same columns in the same order.",
    "UNION · UNION ALL · INTERSECT · EXCEPT · union-compatible · de-dup vs keep")

add_solved_problem("S25 · Hands-on","Rank the merit list and find cross-enrolled students",
    "On the college schema: (a) produce the top-3 merit list of (name, marks); (b) list students enrolled in BOTH IT220 and MGT201.",
    ["(a) Join to get names with marks: SELECT s.name, e.marks FROM Student s, Enrollment e WHERE s.roll=e.roll.",
     "(a) Sort best-first and cap it: ORDER BY e.marks DESC LIMIT 3 → the top three scorers.",
     "(b) Get IT220 rolls: SELECT roll FROM Enrollment WHERE course_id='IT220'.",
     "(b) INTERSECT with MGT201 rolls to keep only students in BOTH courses.",
     "(b) If your MySQL lacks INTERSECT, use WHERE roll IN (…MGT201…) on the IT220 set instead."],
    "(a) SELECT s.name, e.marks FROM Student s, Enrollment e WHERE s.roll=e.roll ORDER BY e.marks DESC LIMIT 3;   (b) SELECT roll FROM Enrollment WHERE course_id='IT220' INTERSECT SELECT roll FROM Enrollment WHERE course_id='MGT201';",
    "~6 min. Show the INTERSECT result, then show the IN-based fallback for older MySQL.")
