add_cheatsheet("Unit 5 · Cheat Sheet","One-page SQL revision reference (MySQL / MariaDB)",
    [("DDL & constraints (S22)","CREATE/ALTER/DROP TABLE. Types: INT, DECIMAL(p,s) for money, VARCHAR/CHAR, DATE, BOOLEAN. Constraints: PRIMARY KEY (=UNIQUE+NOT NULL), FOREIGN KEY, NOT NULL, UNIQUE, CHECK, DEFAULT."),
     ("Query basics (S23–S25)","SELECT cols FROM t WHERE rows; AND/OR/NOT, BETWEEN, IN. AS renames; s1/s2 self-join; LIKE % (any) _ (one). ORDER BY … DESC, LIMIT n; DISTINCT; UNION/INTERSECT/EXCEPT (UNION ALL keeps dups)."),
     ("Aggregates & NULL (S26–S27)","COUNT/SUM/AVG/MIN/MAX; GROUP BY (per group), HAVING (filter groups, aggregates ok). WHERE before, HAVING after. NULL: use IS NULL; aggregates skip NULLs; COALESCE(x,0)."),
     ("Subqueries (S28–S29)","IN=member (=SOME); >SOME=>MIN; >ALL=>MAX; <>ALL=NOT IN. EXISTS=any row; NOT EXISTS='none'/'for all' (double). Beware NOT IN + NULL."),
     ("Views & modify (S30–S32)","Derived relation = subquery in FROM (alias!). VIEW = saved query, no data (not faster). Updatable = single table, no aggregate/join/DISTINCT/derived col; WITH CHECK OPTION. INSERT/UPDATE/DELETE — WHERE or whole table."),
     ("Joins, procs, triggers, index (S33–S35)","INNER=both; LEFT/RIGHT/FULL keep unmatched (NULLs); prefer ON. Procedure=CALL, logic+params. Trigger fires auto (BEFORE/AFTER, OLD/NEW). Index=B-tree; reads faster, writes slower; index selectively.")])

add_glossary("Unit 5 · Glossary","Key terms — quick reference",
    [("DDL","CREATE/ALTER/DROP — defines structure."),
     ("DML","SELECT/INSERT/UPDATE/DELETE — queries & modifies data."),
     ("Constraint","a rule the DBMS enforces on rows (PK/FK/NOT NULL/UNIQUE/CHECK/DEFAULT)."),
     ("PRIMARY KEY","UNIQUE + NOT NULL; one per table."),
     ("FOREIGN KEY","a value that must match a parent table's key."),
     ("DECIMAL(p,s)","exact fixed-point type for money (never FLOAT)."),
     ("Projection (SELECT)","choosing columns."),
     ("Selection (WHERE)","choosing rows whose condition is TRUE."),
     ("Cross / Cartesian product","every row × every row (missing join condition)."),
     ("AS / alias","renames a column or table for output/queries."),
     ("Tuple variable","a table alias; mandatory for self-joins (s1,s2)."),
     ("LIKE","pattern match: % = any sequence, _ = one character."),
     ("ORDER BY","sorts result rows (ASC default / DESC)."),
     ("DISTINCT","removes duplicate rows from the result."),
     ("UNION / INTERSECT / EXCEPT","combine union-compatible result sets."),
     ("Aggregate function","COUNT/SUM/AVG/MIN/MAX — many rows to one value."),
     ("GROUP BY","one aggregate row per group."),
     ("HAVING","filters groups after aggregation (aggregates allowed)."),
     ("NULL","unknown/missing — not 0, not empty string."),
     ("Three-valued logic","TRUE/FALSE/UNKNOWN; use IS NULL, not = NULL."),
     ("COALESCE","returns the first non-NULL argument (a fallback)."),
     ("Subquery","a query nested inside another."),
     ("IN / NOT IN","tests set membership / absence."),
     ("SOME/ANY / ALL","at-least-one / every element comparison."),
     ("EXISTS / NOT EXISTS","tests whether a subquery returns any / no rows."),
     ("Correlated subquery","inner query references the outer row."),
     ("Derived relation","a subquery in FROM (must be aliased)."),
     ("View","a named stored query (virtual table, stores no data)."),
     ("Updatable view","a view whose changes pass to one base table."),
     ("WITH CHECK OPTION","blocks rows that fall outside a view's filter."),
     ("INNER JOIN","keeps only rows matching on both sides."),
     ("OUTER JOIN","LEFT/RIGHT/FULL — keeps unmatched rows (NULL-filled)."),
     ("ON / USING / NATURAL","explicit / shared-column / all-common-names join match."),
     ("Stored procedure","a named, callable block of server-side logic (CALL)."),
     ("IN/OUT/INOUT","stored-procedure parameter directions."),
     ("Trigger","code that fires automatically on INSERT/UPDATE/DELETE."),
     ("OLD / NEW","a trigger's pre-/post-change row values."),
     ("Index","a B-tree structure that speeds lookups (reads↑, writes↓)."),
     ("Clause execution order","FROM→WHERE→GROUP BY→HAVING→SELECT→ORDER BY.")])

